<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Personal Expense Tracker</title>
<style>
  body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    max-width: 700px;
    margin: 20px auto;
    padding: 0 15px;
    color: #333;
  }
  h1, h2 {
    border-bottom: 1px solid #eee;
    padding-bottom: 5px;
  }
  form div, .filters div {
    margin-bottom: 10px;
  }
  label {
    display: inline-block;
    width: 90px;
    font-weight: bold;
  }
  input, select, button {
    padding: 6px;
    font-size: 14px;
  }
  button {
    cursor: pointer;
    background: #007bff;
    color: white;
    border: none;
    border-radius: 4px;
  }
  button:hover {
    background: #0056b3;
  }
  #form-error {
    color: #d9534f;
    margin-top: 5px;
    min-height: 1.2em;
    font-weight: bold;
  }
  .summary-box {
    background: #f9f9f9;
    padding: 15px;
    border-radius: 6px;
    margin-bottom: 20px;
    border: 1px solid #ddd;
  }
  #category-summary div {
    margin: 4px 0;
  }
  .expense {
    display: flex;
    gap: 10px;
    padding: 10px;
    border-bottom: 1px solid #eee;
    align-items: center;
  }
  .expense span {
    flex: 1;
  }
  .expense .exp-del {
    flex: 0 0 auto;
    background: #dc3545;
  }
  .expense .exp-del:hover {
    background: #c82333;
  }
</style>
</head>
<body>

<h1>Personal Expense Tracker</h1>

<form id="expense-form">
  <div>
    <label for="amount">Amount:</label>
    <input type="number" id="amount" step="0.01" min="0" placeholder="0.00">
  </div>
  <div>
    <label for="category">Category:</label>
    <select id="category">
      <option value="groceries">groceries</option>
      <option value="transport">transport</option>
      <option value="bills">bills</option>
      <option value="fun">fun</option>
    </select>
  </div>
  <div>
    <label for="date">Date:</label>
    <input type="date" id="date">
  </div>
  <div>
    <label for="note">Note:</label>
    <input type="text" id="note" placeholder="Optional">
  </div>
  <button type="submit" id="add-expense">Add Expense</button>
  <div id="form-error"></div>
</form>

<h2>Filters</h2>
<div class="filters">
  <div>
    <label for="filter-category">Category:</label>
    <select id="filter-category">
      <option value="all">all</option>
      <option value="groceries">groceries</option>
      <option value="transport">transport</option>
      <option value="bills">bills</option>
      <option value="fun">fun</option>
    </select>
  </div>
  <div>
    <label for="filter-from">From:</label>
    <input type="date" id="filter-from">
    <label for="filter-to" style="width:auto; margin-left:10px;">To:</label>
    <input type="date" id="filter-to">
  </div>
</div>

<div class="summary-box">
  <h2>Summary</h2>
  <div style="font-size: 1.1em; margin-bottom: 10px;">
    <strong>Total (visible):</strong> $<span id="total">0.00</span>
  </div>
  <div id="category-summary">
    <div>groceries: <span class="cat-total" data-cat="groceries">0.00</span></div>
    <div>transport: <span class="cat-total" data-cat="transport">0.00</span></div>
    <div>bills: <span class="cat-total" data-cat="bills">0.00</span></div>
    <div>fun: <span class="cat-total" data-cat="fun">0.00</span></div>
  </div>
</div>

<h2>Expenses</h2>
<div id="expense-list"></div>

<script>
  let expenses = [];
  try {
    const saved = localStorage.getItem('expenses');
    if (saved) {
      const parsed = JSON.parse(saved);
      if (Array.isArray(parsed)) {
        expenses = parsed.filter(e => typeof e.amount === 'number' && e.date && e.category);
      }
    }
  } catch (e) {
    console.error('Failed to load expenses', e);
  }

  const form = document.getElementById('expense-form');
  const amountInput = document.getElementById('amount');
  const categoryInput = document.getElementById('category');
  const dateInput = document.getElementById('date');
  const noteInput = document.getElementById('note');
  const errorEl = document.getElementById('form-error');

  form.addEventListener('submit', e => {
    e.preventDefault();

    const amt = parseFloat(amountInput.value);
    const dt = dateInput.value;

    if (isNaN(amt) || amt <= 0) {
      errorEl.textContent = 'Please enter a valid positive amount.';
      return;
    }
    if (!dt) {
      errorEl.textContent = 'Please select a date.';
      return;
    }

    errorEl.textContent = '';

    const newExpense = {
      id: Date.now() + Math.floor(Math.random() * 1000),
      amount: amt,
      category: categoryInput.value,
      date: dt,
      note: noteInput.value.trim()
    };

    expenses.push(newExpense);
    saveExpenses();

    amountInput.value = '';
    noteInput.value = '';

    renderAll();
  });

  function saveExpenses() {
    try {
      localStorage.setItem('expenses', JSON.stringify(expenses));
    } catch (e) {
      console.error('Failed to save expenses', e);
    }
  }

  function deleteExpense(id) {
    expenses = expenses.filter(e => e.id !== id);
    saveExpenses();
    renderAll();
  }

  function renderAll() {
    const list = document.getElementById('expense-list');
    list.innerHTML = '';

    const sorted = [...expenses].sort((a, b) => {
      if (a.date !== b.date) return b.date.localeCompare(a.date);
      return b.id - a.id;
    });

    sorted.forEach(exp => {
      const row = document.createElement('div');
      row.className = 'expense';
      row.dataset.id = exp.id;
      row.dataset.category = exp.category;
      row.dataset.date = exp.date;

      const amt = document.createElement('span');
      amt.className = 'exp-amount';
      amt.textContent = exp.amount.toFixed(2);

      const cat = document.createElement('span');
      cat.className = 'exp-category';
      cat.textContent = exp.category;

      const dt = document.createElement('span');
      dt.className = 'exp-date';
      dt.textContent = exp.date;

      if (exp.note) {
        const noteSpan = document.createElement('span');
        noteSpan.textContent = exp.note;
        noteSpan.style.fontSize = '0.9em';
        noteSpan.style.color = '#666';
        row.appendChild(noteSpan);
      }

      const del = document.createElement('button');
      del.className = 'exp-del';
      del.textContent = 'Delete';
      del.addEventListener('click', () => deleteExpense(exp.id));

      row.appendChild(amt);
      row.appendChild(cat);
      row.appendChild(dt);
      row.appendChild(del);

      list.appendChild(row);
    });

    applyFilters();
  }

  function applyFilters() {
    const fCat = document.getElementById('filter-category').value;
    const fFrom = document.getElementById('filter-from').value;
    const fTo = document.getElementById('filter-to').value;

    let totalVisible = 0;
    const catSums = {};

    const rows = document.querySelectorAll('.expense');
    rows.forEach(row => {
      const id = parseInt(row.dataset.id, 10);
      const exp = expenses.find(e => e.id === id);
      if (!exp) return;

      let show = true;
      if (fCat !== 'all' && exp.category !== fCat) show = false;
      if (fFrom && exp.date < fFrom) show = false;
      if (fTo && exp.date > fTo) show = false;

      row.style.display = show ? '' : 'none';

      if (show) {
        totalVisible += exp.amount;
        catSums[exp.category] = (catSums[exp.category] || 0) + exp.amount;
      }
    });

    document.getElementById('total').textContent = totalVisible.toFixed(2);

    document.querySelectorAll('.cat-total').forEach(el => {
      const cat = el.dataset.cat;
      const sum = catSums[cat] || 0;
      el.textContent = sum.toFixed(2);
    });
  }

  ['change', 'input'].forEach(evt => {
    document.getElementById('filter-category').addEventListener(evt, applyFilters);
    document.getElementById('filter-from').addEventListener(evt, applyFilters);
    document.getElementById('filter-to').addEventListener(evt, applyFilters);
  });

  renderAll();
</script>
</body>
</html>
